def calc(expr):
    s = expr
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit() or c == '.':
            j = i
            while j < n and (s[j].isdigit() or s[j] == '.'):
                j += 1
            num_str = s[i:j]
            tokens.append(float(num_str) if '.' in num_str else int(num_str))
            i = j
            continue
        if c == '*' and i + 1 < n and s[i + 1] == '*':
            tokens.append('**')
            i += 2
            continue
        if c == '/' and i + 1 < n and s[i + 1] == '/':
            tokens.append('//')
            i += 2
            continue
        if c in '+-*/%()':
            tokens.append(c)
            i += 1
            continue
        i += 1

    pos = 0
    def peek():
        return tokens[pos] if pos < len(tokens) else None
    def consume():
        nonlocal pos
        t = tokens[pos]
        pos += 1
        return t

    def parse_expression():
        val = parse_term()
        while True:
            op = peek()
            if op == '+' or op == '-':
                consume()
                right = parse_term()
                val = val + right if op == '+' else val - right
            else:
                break
        return val

    def parse_term():
        val = parse_unary()
        while True:
            op = peek()
            if op in ('*', '/', '//', '%'):
                consume()
                right = parse_unary()
                if op == '*':
                    val = val * right
                elif op == '/':
                    val = val / right
                elif op == '//':
                    val = val // right
                else:
                    val = val % right
            else:
                break
        return val

    def parse_unary():
        op = peek()
        if op == '+' or op == '-':
            consume()
            operand = parse_unary()
            return operand if op == '+' else -operand
        return parse_power()

    def parse_power():
        left = parse_primary()
        if peek() == '**':
            consume()
            right = parse_unary()
            return left ** right
        return left

    def parse_primary():
        tok = peek()
        if tok == '(':
            consume()
            val = parse_expression()
            if peek() != ')':
                raise ValueError('missing )')
            consume()
            return val
        if isinstance(tok, (int, float)):
            consume()
            return tok
        raise ValueError('unexpected token')

    result = parse_expression()
    return result
