import numpy as np
import numba

@numba.njit
def _count(arr, tmp, left, right):
    if right - left <= 1:
        return 0
    mid = (left + right) // 2
    inv = _count(arr, tmp, left, mid) + _count(arr, tmp, mid, right)
    i = left
    j = mid
    k = left
    while i < mid and j < right:
        if arr[i] <= arr[j]:
            tmp[k] = arr[i]
            i += 1
        else:
            tmp[k] = arr[j]
            inv += mid - i
            j += 1
        k += 1
    while i < mid:
        tmp[k] = arr[i]
        i += 1
        k += 1
    while j < right:
        tmp[k] = arr[j]
        j += 1
        k += 1
    for k in range(left, right):
        arr[k] = tmp[k]
    return inv

def count_inversions(nums):
    if not nums:
        return 0
    arr = np.array(nums, dtype=np.int64)
    tmp = np.empty_like(arr)
    return int(_count(arr, tmp, 0, arr.size))
